package org.cttelsamicsterrassa.data.core.application.player.delete;
import org.albertsanso.commons.command.*; import org.cttelsamicsterrassa.data.core.domain.player.repository.PlayerSeasonRepository; import javax.inject.*;
@Named public class DeletePlayerSeasonCommandHandler extends DomainCommandHandler<DeletePlayerSeasonCommand>{private final PlayerSeasonRepository r;@Inject public DeletePlayerSeasonCommandHandler(PlayerSeasonRepository r){this.r=r;}public DomainCommandResponse handle(DeletePlayerSeasonCommand c){return r.findPlayerSeasonById(c.getPlayerSeasonId()).map(p->{p.delete();r.deletePlayerSeasonById(c.getPlayerSeasonId());return DomainCommandResponse.successResponse("Player season deleted successfully: "+c.getPlayerSeasonId());}).orElseGet(()->DomainCommandResponse.successResponse("Player season not found: "+c.getPlayerSeasonId()));}}
